head.script:
scwin.gVar = {
    "cID" : ""
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof scwin.target1 !== 'undefined') {
        scwin.target1.remove();
    }

    // 조건 설정 (gridLayout 은 id 기반 CSS 규칙을 생성하므로 빈 id 금지 → 기본값 target1)
    let cID = scwin.gVar["cID"];

    // comp 생성 (createBasicGridLayout 내용 인라인 — id = cID)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (gridLayout : 2열 x 3행, 자식 없이 빈 상태)
    let strTarget = '';
    strTarget += '<w2:gridLayout ' + strNameSpace + ' style="width:400px; height:200px;" gridTemplateColumns="1fr 1fr;" gridTemplateRows="40px 40px 40px;" gridColumnGap="1px;" gridRowGap="1px;" gridColumn="1:1:1:2:2:2;" gridRow="1:2:3:1:2:3;" rowShow="1:1:1:1:1:1;">';
    strTarget += '</w2:gridLayout>';

    scwin.target1 = await $p.dynamicCreate(
        cID,
        "gridLayout",
        strTarget,
        grp_comp
    );

    // 각 cell 을 자식 group + 내부 textbox 로 별도 생성 → 6 cell 그리드 배치
    for (let i = 1; i <= 6; i++) {
        let cellBg = (i <= 2) ? 'silver' : 'white';

        let strGroup = '<xf:group ' + strNameSpace + ' style="background-color: ' + cellBg + ';"></xf:group>';
        scwin['group' + i] = await $p.dynamicCreate('group' + i, 'group', strGroup, scwin.target1);

        let strTbx = '<w2:textbox ' + strNameSpace + ' id="" style="width:150px; height:23px;"></w2:textbox>';
        scwin['tbx' + i] = await $p.dynamicCreate('tbx' + i, 'textbox', strTbx, scwin['group' + i]);
        scwin['tbx' + i].setValue('텍스트 ' + i);
    }
}
